"""Remote preparation tests use generated bytes and mocked HTTP only."""

import hashlib
import io
import json
from pathlib import Path

import numpy as np
import pytest

from unilab.data import amass_download as download


def _payload(frames=80):
    stream = io.BytesIO()
    np.savez(
        stream,
        poses=np.zeros((frames, 156)),
        trans=np.zeros((frames, 3)),
        betas=np.zeros(16),
        gender=np.array("male"),
        mocap_framerate=np.array(120.0),
    )
    return stream.getvalue()


def _entry(source="raw/CMU/01/01_01_poses.npz", payload=None):
    payload = _payload() if payload is None else payload
    return {
        "source_path": source,
        "sha256": hashlib.sha256(payload).hexdigest(),
        "bytes": len(payload),
        "subject": source.split("/")[2],
    }


def test_selection_is_deterministic_round_robin_and_filters_ineligible():
    entries = [
        _entry(f"raw/CMU/{s}/{s}_{i:02}_poses.npz") for s in ("01", "02") for i in range(1, 4)
    ]
    tree = [
        {"path": e["source_path"], "type": "file", "size": e["bytes"], "lfs": {"oid": e["sha256"]}}
        for e in entries
    ]
    tree += [{"path": "raw/CMU/03/03_01_poses.npz", "type": "file", "size": 5 * 1024**2}]
    selected = download._select(tree, 4)
    assert selected == download._select(list(reversed(tree)), 4)
    assert [e["subject"] for e in selected] == ["01", "02", "01", "02"]
    with pytest.raises(ValueError, match="eligible"):
        download._select(tree, 7)


def test_tree_pagination(monkeypatch):
    class Response(io.BytesIO):
        def __init__(self, content, link=""):
            super().__init__(json.dumps(content).encode())
            self.headers = {"Link": link}

    next_url = f"https://huggingface.co/api/datasets/{download.REPOSITORY}/tree/{download.REVISION}/raw/CMU?cursor=next"
    responses = iter(
        [Response([{"path": "a"}], f'<{next_url}>; rel="next"'), Response([{"path": "b"}])]
    )
    monkeypatch.setattr(download, "urlopen", lambda *args, **kwargs: next(responses))
    assert download._source_tree() == [{"path": "a"}, {"path": "b"}]


def test_download_verifies_and_reuses_existing_file(tmp_path, monkeypatch):
    payload = _payload()
    calls = []

    def open_mock(url, **kwargs):
        calls.append(url)
        return io.BytesIO(payload)

    monkeypatch.setattr(download, "urlopen", open_mock)
    entry = _entry(payload=payload)
    result = download._download(entry, tmp_path)
    assert result["frames"] == 80
    assert result["fps"] == 120
    assert result["model_type"] == "unknown"
    assert download._download(entry, tmp_path) == result
    assert len(calls) == 1
    assert download.REVISION in calls[0]
    assert not list(tmp_path.rglob("*.part"))


@pytest.mark.parametrize("fault", ["short", "oversized", "wrong_hash"])
def test_failed_download_leaves_no_final_or_partial_file(tmp_path, monkeypatch, fault):
    payload = _payload()
    entry = _entry(payload=payload)
    broken = payload[:-1] if fault == "short" else payload + b"extra"
    if fault == "wrong_hash":
        broken = b"x" * len(payload)
    monkeypatch.setattr(download, "urlopen", lambda *args, **kwargs: io.BytesIO(broken))
    with pytest.raises(ValueError, match="size|verification"):
        download._download(entry, tmp_path)
    assert not (tmp_path / entry["source_path"]).exists()
    assert not list(tmp_path.rglob("*.part"))


def test_corrupted_existing_file_and_escaping_path_are_rejected(tmp_path, monkeypatch):
    def unexpected(*args, **kwargs):
        pytest.fail("No HTTP request should occur")

    monkeypatch.setattr(download, "urlopen", unexpected)
    entry = _entry()
    target = tmp_path / entry["source_path"]
    target.parent.mkdir(parents=True)
    target.write_bytes(b"damaged")
    with pytest.raises(ValueError, match="Existing file"):
        download._download(entry, tmp_path)
    assert target.read_bytes() == b"damaged"
    with pytest.raises(ValueError, match="source path"):
        download._download({**entry, "source_path": "../escape.npz"}, tmp_path)


def test_preparation_writes_verified_manifest_and_subject_split(tmp_path, monkeypatch):
    payload = _payload()
    entries = [
        _entry(f"raw/CMU/{s}/{s}_{i:02}_poses.npz", payload) for s in ("01", "02") for i in (1, 2)
    ]
    monkeypatch.setattr(download, "_source_tree", lambda: [])
    monkeypatch.setattr(download, "_select", lambda *args: entries)
    monkeypatch.setattr(download, "urlopen", lambda *args, **kwargs: io.BytesIO(payload))
    summary = download.prepare_amass_subset(tmp_path, workers=2)
    assert summary == {"clips": 4, "bytes": 4 * len(payload), "frames": 320, "subjects": 2}
    manifest = json.loads((tmp_path / "manifest.json").read_text())
    split = json.loads((tmp_path / "splits.json").read_text())
    assert manifest["revision"] == download.REVISION
    assert len(manifest["files"]) == 4

    def subject(files):
        return {Path(p).parts[2] for p in files}

    assert subject(split["train"]).isdisjoint(subject(split["validation"]))
    assert len(split["train"]) == len(split["validation"]) == 2
    assert split["excluded_short"] == []
    assert not list(tmp_path.rglob("*.part"))
